import { Link } from "react-router-dom";
import React, { useEffect, useState } from "react";
import PropTypes from "prop-types";
import { getAllCars, deleteCarById } from "../../services/ApiCar";

export default function CardVoiture({ color = "light" }) {
  const [cars, setCars] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [searchTerm, setSearchTerm] = useState("");

  const fetchCars = async () => {
    try {
      setLoading(true);
      const res = await getAllCars();
      setCars(res.data);
    } catch (err) {
      setError("Erreur lors du chargement des voitures");
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async (id) => {
    if (window.confirm("Êtes-vous sûr de vouloir supprimer cette voiture ?")) {
      try {
        await deleteCarById(id);
        fetchCars();
      } catch (err) {
        setError("Erreur lors de la suppression");
        console.error(err);
      }
    }
  };

  useEffect(() => {
    fetchCars();
  }, []);

  const filteredCars = cars.filter(car => 
    car.model.toLowerCase().includes(searchTerm.toLowerCase()) ||
    car.matricule.toLowerCase().includes(searchTerm.toLowerCase())
  );

  if (loading) return <div className="text-center py-8">Chargement...</div>;
  if (error) return <div className="text-center py-8 text-red-500">{error}</div>;

  return (
    <div className={`relative flex flex-col min-w-0 break-words w-full mb-6 shadow-lg rounded ${
      color === "light" ? "bg-white" : "bg-lightBlue-900 text-white"
    }`}>
      <div className="rounded-t mb-0 px-4 py-3 border-0">
        <div className="flex flex-wrap items-center justify-between">
          <div className="relative px-4 max-w-full flex-grow flex-1">
            <h3 className={`font-semibold text-lg ${
              color === "light" ? "text-blueGray-700" : "text-white"
            }`}>
              Liste des Voitures
            </h3>
          </div>
          <div className="flex items-center gap-4">
            <input
              type="text"
              placeholder="Rechercher..."
              className="px-3 py-1 border rounded"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
            <Link to="/admin/AddVoiture">
              <button className="bg-green-500 hover:bg-green-600 text-white font-semibold text-sm px-4 py-2 rounded shadow transition">
                ➕ Ajouter
              </button>
            </Link>
          </div>
        </div>
      </div>

      <div className="block w-full overflow-x-auto">
        {filteredCars.length === 0 ? (
          <div className="text-center py-8">
            <p>Aucune voiture trouvée</p>
          </div>
        ) : (
          <table className="items-center w-full bg-transparent border-collapse">
            <thead>
              <tr>
                <th className="px-6 py-3 text-left text-xs font-semibold uppercase">Modèle</th>
                <th className="px-6 py-3 text-left text-xs font-semibold uppercase">Marque</th>
                <th className="px-6 py-3 text-left text-xs font-semibold uppercase">Matricule</th>
                <th className="px-6 py-3 text-left text-xs font-semibold uppercase">Prix/jour</th>
                <th className="px-6 py-3 text-center text-xs font-semibold uppercase">Actions</th>
              </tr>
            </thead>
            <tbody>
              {filteredCars.map((car) => (
                <tr key={car._id} className="hover:bg-gray-50">
                  <td className="border-t-0 px-6 py-4 align-middle text-sm">{car.model}</td>
                  <td className="border-t-0 px-6 py-4 align-middle text-sm">{car.marque}</td>
                  <td className="border-t-0 px-6 py-4 align-middle text-sm font-medium">{car.matricule}</td>
                  <td className="border-t-0 px-6 py-4 align-middle text-sm">{car.prix_jour} €</td>
                  <td className="border-t-0 px-6 py-4 align-middle text-center">
                    <div className="flex items-center justify-center gap-2">
                      <Link to={`/admin/UpdateVoiture/${car._id}`} state={{ car }}>
                        <button className="bg-blue-500 hover:bg-blue-600 text-white text-xs font-semibold py-2 px-3 rounded shadow transition">
                          ✏️ Modifier
                        </button>
                      </Link>
                      <button
                        onClick={() => handleDelete(car._id)}
                        className="bg-red-500 hover:bg-red-600 text-white text-xs font-semibold py-2 px-3 rounded shadow transition"
                      >
                        🗑️ Supprimer
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
}

CardVoiture.propTypes = {
  color: PropTypes.oneOf(["light", "dark"]),
};
